import { bi as b, Lesson, Activity } from './model';

// Original bilingual explanations. Curriculum mapping: Academy 2026 guide, pp. 6–7.
// Each row: title, explanation, example, question, correct answer, distractor 1, distractor 2 (RU / KK).
type Row = [string,string,string,string,string,string,string,string,string,string,string,string,string,string];
const all: Lesson[] = [];
function unit(grade: number, ru: string, kk: string, icon: string, rows: Row[]) {
  rows.forEach(r => {
    const id = `g${grade}-${String(all.filter(l => l.grade === grade).length + 1).padStart(2,'0')}`;
    const check = { kind: 'choice' as const, prompt: b(r[6], r[7]), options: [b(r[8],r[9]),b(r[10],r[11]),b(r[12],r[13])], answer: 0, why: b(r[4],r[5]) };
    all.push({id, grade, unit: b(ru,kk), title:b(r[0],r[1]), icon, cards:[{title:b('Разберёмся','Түсініп алайық'),text:b(r[2],r[3])},{title:b('Посмотри на пример','Мысалға назар аудар'),text:b(r[4],r[5])}],activity:check,check,source:'academy-2026'});
  });
}
unit(1,'Знакомство с компьютером','Компьютермен танысу','desktop-outline',[
['Из чего состоит компьютер','Компьютер неден тұрады','Клавиатура и мышь передают команды компьютеру. Монитор показывает результат. Системный блок обрабатывает информацию.','Пернетақта мен тінтуір компьютерге командалар береді. Монитор нәтижені көрсетеді. Жүйелік блок ақпаратты өңдейді.','Ты нажал букву на клавиатуре — она появилась на мониторе. Клавиатура вводит, монитор выводит информацию.','Пернетақтадан әріп бастың — ол мониторда көрінді. Пернетақта ақпаратты енгізеді, монитор шығарады.','На чём появляется рисунок?','Сурет қайда көрсетіледі?','На мониторе','Мониторда','На мыши','Тінтуірде','На клавиатуре','Пернетақтада'],
['Работаем безопасно','Қауіпсіз жұмыс істейміз','Сиди удобно, держи спину прямо и не наклоняйся близко к экрану. Делай перерывы. Провода и розетки трогает взрослый.','Ыңғайлы отыр, арқаңды тік ұста, экранға тым жақындама. Үзіліс жаса. Сымдар мен розеткаларды ересек адам ұстайды.','Рядом с ноутбуком пролилась вода? Отойди и сразу позови взрослого. Не пытайся сам вытащить мокрый провод.','Ноутбук жанына су төгілді ме? Алыста да, ересек адамды шақыр. Дымқыл сымды өзің суырма.','Что делать, если пролилась вода?','Су төгілсе не істеу керек?','Позвать взрослого','Ересек адамды шақыру','Продолжить игру','Ойынды жалғастыру','Трогать провода','Сымдарды ұстау'],
['Рабочий стол и файлы','Жұмыс үстелі және файлдар','На рабочем столе есть значки. Файл хранит рисунок или текст, папка помогает их упорядочить. Окно можно свернуть, развернуть или закрыть.','Жұмыс үстелінде белгішелер бар. Файл суретті не мәтінді сақтайды, бума оларды реттейді. Терезені қайыруға, жаюға немесе жабуға болады.','Чтобы рисунок остался, нажми «Сохранить» и выбери папку. В следующий раз команда «Открыть» поможет найти его.','Сурет сақталуы үшін «Сақтау» пәрменін басып, буманы таңда. Кейін «Ашу» пәрменімен оны табасың.','Какая команда оставит рисунок на потом?','Қай пәрмен суретті кейінге сақтайды?','Сохранить','Сақтау','Закрыть без сохранения','Сақтамай жабу','Удалить','Жою']]);
unit(1,'Мой первый рисунок','Менің алғашқы суретім','color-palette-outline',[
['Рисуем фигурами','Пішіндермен сурет саламыз','Из простых фигур можно составить картинку. Сначала выбери фигуру, потом размести её на холсте. Цвет помогает выделить детали.','Қарапайым пішіндерден сурет құрауға болады. Алдымен пішінді таңда, кейін оны кенепке орналастыр. Түс бөлшектерді ерекшелейді.','Домик можно собрать из квадрата и треугольника: квадрат станет стенами, треугольник — крышей.','Шаршы мен үшбұрыштан үй құрауға болады: шаршы — қабырға, үшбұрыш — шатыр.','Какая фигура подойдёт для крыши?','Шатырға қай пішін сәйкес келеді?','Треугольник','Үшбұрыш','Точка','Нүкте','Овал','Сопақша'],
['Копируем детали','Бөлшектерді көшіреміз','Выделение показывает, какую часть рисунка ты меняешь. Копирование запоминает выделенную часть, а вставка создаёт её копию.','Ерекшелеу суреттің қай бөлігін өзгертетініңді көрсетеді. Көшіру сол бөлікті есте сақтайды, қою оның көшірмесін жасайды.','Нарисуй одно окно, выдели его, скопируй и вставь. Теперь у домика два одинаковых окна.','Бір терезе сал, оны ерекшеле, көшір де қой. Енді үйде екі бірдей терезе бар.','Что сделать перед копированием окна?','Терезені көшірмес бұрын не істеу керек?','Выделить окно','Терезені ерекшелеу','Удалить дом','Үйді жою','Закрыть рисунок','Суретті жабу'],
['Меняем фигуры','Пішіндерді өзгертеміз','У фигуры есть заливка внутри и контур по краю. Фигуру можно увеличить, уменьшить или повернуть.','Пішіннің ішінде бояуы, шетінде контуры бар. Пішінді үлкейтуге, кішірейтуге немесе бұруға болады.','Чтобы сделать солнце жёлтым внутри, измени заливку круга. Изменение контура перекрасит только его край.','Күннің ішін сары ету үшін дөңгелектің бояуын өзгерт. Контурды өзгертсең, тек шеті боялады.','Что меняет цвет внутри круга?','Дөңгелектің ішкі түсін не өзгертеді?','Заливка','Ішін бояу','Контур','Контур','Поворот','Бұру']]);
unit(1,'Алгоритмы и Scratch','Алгоритмдер және Scratch','code-slash-outline',[
['Команды по порядку','Ретімен орындалатын командалар','Алгоритм — понятный порядок действий для решения задачи. Если перепутать шаги, результат может измениться.','Алгоритм — есепті шешуге арналған түсінікті әрекеттер реті. Қадамдардың орнын ауыстырсаң, нәтиже өзгеруі мүмкін.','Чтобы вымыть руки: намочи их, намыль, смой мыло, вытри полотенцем. Вытирать руки до мытья бессмысленно.','Қолды жуу үшін: сула, сабында, сабынды шай, сүлгімен сүрт. Жумай тұрып сүртудің пайдасы жоқ.','Что такое алгоритм?','Алгоритм деген не?','Порядок действий','Әрекеттер реті','Любой рисунок','Кез келген сурет','Название компьютера','Компьютердің атауы'],
['Знакомимся со Scratch','Scratch-пен танысамыз','В Scratch программу собирают из блоков. Персонажа называют спрайтом. Он выполняет команды на сцене.','Scratch-та программа блоктардан құралады. Кейіпкер спрайт деп аталады. Ол сахнада командаларды орындайды.','Блок движения перемещает кота. Блок внешности может показать реплику. Команды выбираем по задаче.','Қозғалыс блогы мысықты жылжытады. Келбет блогы сөзін көрсете алады. Команданы мақсатқа сай таңдаймыз.','Кто выполняет команды на сцене?','Сахнада командаларды кім орындайды?','Спрайт','Спрайт','Папка','Бума','Клавиатура сама по себе','Пернетақта өздігінен'],
['Первая программа','Алғашқы программа','Чтобы программа начала работать, ей нужно событие запуска. После блока запуска поставь команды в нужном порядке.','Программа жұмыс істеуі үшін іске қосу оқиғасы қажет. Іске қосу блогынан кейін командаларды қажетті ретпен орналастыр.','Событие «зелёный флаг» → шаг вперёд → сказать «Привет!». При запуске герой сначала движется, затем здоровается.','«Жасыл жалау» оқиғасы → алға қадам → «Сәлем!» деу. Іске қосқанда кейіпкер алдымен жүреді, кейін амандасады.','Что запускает эту программу?','Бұл программаны не іске қосады?','Нажатие зелёного флага','Жасыл жалауды басу','Цвет фона','Фонның түсі','Имя папки','Буманың атауы']]);
unit(1,'Умные помощники','Ақылды көмекшілер','sparkles-outline',[
['Что умеют умные программы','Ақылды программалар не істей алады','Некоторые программы умеют распознавать речь или находить предметы на картинке. Им помогают методы искусственного интеллекта. Они не думают и не чувствуют как человек.','Кейбір программалар сөйлеуді таниды немесе суреттен заттарды табады. Оларға жасанды интеллект әдістері көмектеседі. Олар адам сияқты ойламайды және сезбейді.','Робот — устройство, а ИИ — технология. Не каждый робот использует ИИ: игрушка может просто выполнять готовые команды.','Робот — құрылғы, ал ЖИ — технология. Әр робот ЖИ қолданбайды: ойыншық дайын командаларды ғана орындауы мүмкін.','Каждый ли робот использует ИИ?','Әр робот ЖИ қолдана ма?','Нет, он может выполнять готовые команды','Жоқ, ол дайын командаларды орындай алады','Да, всегда','Иә, әрқашан','Роботы — живые существа','Роботтар — тірі ағзалар']]);

unit(2,'Компьютеры и программы','Компьютерлер мен программалар','desktop-outline',[
['Устройства ввода и вывода','Енгізу және шығару құрылғылары','Микрофон вводит звук, клавиатура — текст, мышь — команды. Наушники выводят звук, принтер печатает, монитор показывает изображение.','Микрофон дыбысты, пернетақта мәтінді, тінтуір команданы енгізеді. Құлаққап дыбысты шығарады, принтер басып шығарады, монитор суретті көрсетеді.','Чтобы записать голос, нужен микрофон. Чтобы послушать запись и не мешать другим, нужны наушники.','Дауысты жазу үшін микрофон керек. Жазбаны басқаларға кедергі келтірмей тыңдау үшін құлаққап керек.','Что вводит голос в компьютер?','Компьютерге дауысты не енгізеді?','Микрофон','Микрофон','Принтер','Принтер','Монитор','Монитор'],
['Безопасность в интернете','Интернеттегі қауіпсіздік','Не сообщай незнакомцам адрес, пароль и номер телефона. Если сообщение пугает или просит что-то скрыть, прекрати общение и обратись к взрослому.','Бейтаныс адамға мекенжайыңды, құпиясөзіңді, телефон нөміріңді айтпа. Хабарлама қорқытса не бір нәрсені жасыруды сұраса, сөйлесуді тоқтатып, ересекке айт.','Сообщение «Ты выиграл! Пришли пароль» опасно. Для получения приза твой пароль не нужен.','«Сен ұттың! Құпиясөзіңді жібер» деген хабарлама қауіпті. Сыйлық алу үшін құпиясөзің қажет емес.','Незнакомец просит пароль. Что делать?','Бейтаныс адам құпиясөз сұрады. Не істейсің?','Не отправлять и сообщить взрослому','Жібермей, ересекке айту','Отправить быстрее','Тезірек жіберу','Отправить пароль друга','Досыңның құпиясөзін жіберу'],
['Порядок в файлах','Файлдарды реттеу','Папки объединяют файлы по назначению. Копирование оставляет исходный файл, перемещение меняет его место. Удаление убирает файл.','Бумалар файлдарды мақсатына қарай біріктіреді. Көшіру бастапқы файлды сақтайды, жылжыту орнын өзгертеді. Жою файлды алып тастайды.','Фотографии храним в папке «Фото», рассказы — в «Тексты». Перед удалением проверяем, что выбрали нужный файл.','Фотоларды «Фото», әңгімелерді «Мәтіндер» бумасында сақтаймыз. Жоймас бұрын қажетті файлды таңдағанымызды тексереміз.','Какая операция оставляет оригинал?','Қай әрекет түпнұсқаны сақтайды?','Копирование','Көшіру','Удаление','Жою','Перемещение','Жылжыту']]);
unit(2,'Творчество и программы','Шығармашылық және программалар','code-slash-outline',[
['Если — то — иначе','Егер — онда — әйтпесе','Условие помогает выбрать действие. Если условие истинно, выполняется одна ветка. Иначе выполняется другая.','Шарт әрекетті таңдауға көмектеседі. Шарт ақиқат болса, бір тармақ орындалады. Әйтпесе басқа тармақ орындалады.','Если идёт дождь — возьми зонт, иначе — иди без зонта. Сначала проверяем погоду, потом выбираем действие.','Егер жаңбыр жауса — қолшатыр ал, әйтпесе қолшатырсыз шық. Алдымен ауа райын тексеріп, кейін әрекетті таңдаймыз.','Идёт дождь. Какую ветку выбираем?','Жаңбыр жауып тұр. Қай тармақты таңдаймыз?','Взять зонт','Қолшатыр алу','Убрать зонт','Қолшатырды жинау','Не проверять условие','Шартты тексермеу'],
['Исправляем программу','Программаны түзетеміз','Программу нужно проверять. Сравни ожидаемый результат с настоящим, найди неверную команду и запусти исправленный вариант.','Программаны тексеру керек. Күткен нәтижеңді нақты нәтижемен салыстыр, қате команданы тауып, түзетілген нұсқаны іске қос.','Герой должен идти вправо, но пошёл влево. Замени команду направления, затем проверь маршрут ещё раз.','Кейіпкер оңға жүруі керек еді, бірақ солға кетті. Бағыт командасын ауыстырып, жолды қайта тексер.','Что делать после исправления?','Түзеткеннен кейін не істеу керек?','Запустить и проверить','Іске қосып, тексеру','Сразу удалить проект','Жобаны бірден жою','Не смотреть результат','Нәтижеге қарамау']]);
unit(2,'Мультимедиа','Мультимедиа','musical-notes-outline',[
['Знакомство с клавиатурой','Пернетақтамен танысу','Буквы вводят текст. Пробел отделяет слова. Enter начинает новую строку. Backspace удаляет символ слева от курсора.','Әріптер мәтін енгізеді. Бос орын сөздерді бөледі. Enter жаңа жол бастайды. Backspace меңзердің сол жағындағы таңбаны өшіреді.','В слове «котт» лишняя последняя буква. Поставь курсор после неё и нажми Backspace один раз.','«Атт» сөзінде соңғы әріп артық. Меңзерді оның соңына қойып, Backspace пернесін бір рет бас.','Какая клавиша разделяет слова?','Сөздерді қай перне бөледі?','Пробел','Бос орын','Backspace','Backspace','Escape','Escape'],
['Разговор персонажей','Кейіпкерлердің сөйлесуі','В диалоге персонажи говорят по очереди. Пауза помогает дождаться ответа. Реплики должны быть понятными и вежливыми.','Диалогта кейіпкерлер кезекпен сөйлейді. Кідіріс жауапты күтуге көмектеседі. Сөздер түсінікті әрі сыпайы болуы керек.','Кот говорит «Привет!». Второй герой ждёт, затем отвечает «Сәлем!». Без ожидания реплики могут появиться одновременно.','Мысық «Привет!» дейді. Екінші кейіпкер күтіп, кейін «Сәлем!» деп жауап береді. Күтпесе, сөздер бір уақытта шығуы мүмкін.','Как не перебивать первого героя?','Бірінші кейіпкердің сөзін қалай бөлмейміз?','Добавить ожидание','Күту командасын қосу','Сделать текст огромным','Мәтінді өте үлкен ету','Убрать сцену','Сахнаны алып тастау'],
['Записываем и меняем звук','Дыбысты жазу және өңдеу','Звук можно записать, прослушать и обрезать. Перед записью проверь микрофон. Чужой голос записывай только с разрешения.','Дыбысты жазуға, тыңдауға және қысқартуға болады. Жазбас бұрын микрофонды тексер. Өзгенің дауысын тек рұқсатымен жаз.','В начале записи пять секунд тишины. Обрежь ненужное начало, послушай результат и сохрани запись.','Жазба басында бес секунд үнсіздік бар. Қажетсіз басын қысқарт, нәтижені тыңда да сақта.','Как убрать тишину в начале записи?','Жазба басындағы үнсіздікті қалай алып тастаймыз?','Обрезать начало','Басын қысқарту','Увеличить громкость','Дыбысын күшейту','Изменить цвет','Түсін өзгерту'],
['Создаём мультфильм','Мультфильм жасаймыз','Мультфильм создаёт ощущение движения сменой кадров или костюмов. Сначала придумай короткую историю, потом настрой действия героев.','Мультфильм кадрларды не костюмдерді ауыстырып, қозғалыс әсерін береді. Алдымен қысқа оқиға ойлап тап, кейін кейіпкерлер әрекетін бапта.','Два костюма птицы: крылья вверх и вниз. Чередование костюмов с небольшой паузой похоже на взмах крыльев.','Құстың екі костюмі бар: қанаты жоғары және төмен. Оларды қысқа кідіріспен ауыстыру қанат қағуға ұқсайды.','Что создаёт движение крыльев?','Қанат қозғалысын не жасайды?','Чередование костюмов','Костюмдерді кезектестіру','Удаление героя','Кейіпкерді жою','Одно неподвижное изображение','Бір қозғалмайтын сурет']]);
unit(2,'Роботы в нашей жизни','Өміріміздегі роботтар','hardware-chip-outline',[
['Знакомимся с роботом','Роботпен танысамыз','Робот выполняет программу. Моторы двигают его части. Датчики сообщают об окружающем мире. Контроллер управляет работой.','Робот программаны орындайды. Моторлар оның бөліктерін қозғайды. Датчиктер қоршаған орта туралы хабарлайды. Контроллер жұмысты басқарады.','У робота-пылесоса мотор вращает колёса, а датчик помогает заметить препятствие. Это разные задачи.','Робот-шаңсорғыштың моторы дөңгелекті айналдырады, ал датчигі кедергіні байқауға көмектеседі. Олардың міндеттері әртүрлі.','Что вращает колёса?','Дөңгелекті не айналдырады?','Мотор','Мотор','Рисунок','Сурет','Имя робота','Роботтың аты'],
['Движение робота','Роботтың қозғалысы','Маршрут состоит из движений и поворотов. Сначала определи начало и цель. Затем составь команды и проверь их.','Бағыт қозғалыстар мен бұрылыстардан тұрады. Алдымен басталу нүктесі мен мақсатты анықта. Кейін командалар құрып, тексер.','Две клетки вправо и одна вниз: → → ↓. Если изменить порядок, робот пройдёт другим путём.','Екі тор оңға, бір тор төмен: → → ↓. Ретін өзгертсең, робот басқа жолмен жүреді.','Что нужно определить до маршрута?','Бағыт құрмас бұрын нені анықтау керек?','Начало и цель','Басталу нүктесі мен мақсатты','Только цвет робота','Тек роботтың түсін','Имя файла','Файл атауын'],
['Звуковые сигналы робота','Роботтың дыбыстық белгілері','Звук может сообщать о начале, завершении или ошибке. Команда звука выполняется в том месте программы, куда ты её поставишь.','Дыбыс басталу, аяқталу немесе қате туралы хабарлай алады. Дыбыс командасы программаның өзің қойған жерінде орындалады.','Поставь короткий сигнал после достижения цели. Робот сначала приедет, потом сообщит об окончании пути.','Мақсатқа жеткеннен кейін қысқа белгі қой. Робот алдымен жетіп, кейін жолдың аяқталғанын хабарлайды.','Где поставить сигнал о финише?','Мәре белгісін қайда қою керек?','После движения к цели','Мақсатқа қозғалғаннан кейін','До старта','Бастамас бұрын','Вместо всех движений','Барлық қозғалыстың орнына'],
['Выходим из лабиринта','Лабиринттен шығамыз','В лабиринте нужно учитывать стены. Датчик касания сообщает о соприкосновении. По этому сигналу программа может остановить робота и повернуть.','Лабиринтте қабырғаларды ескеру керек. Жанасу датчигі тиіп кеткенін хабарлайды. Осы белгі бойынша программа роботты тоқтатып, бұра алады.','Если датчик нажат — остановись, отъедь и выбери другой путь. Не продолжай ехать прямо в стену.','Егер датчик басылса — тоқта, кері жүріп, басқа жол таңда. Қабырғаға қарай жүре берме.','Датчик коснулся стены. Что безопаснее?','Датчик қабырғаға тиді. Қайсысы қауіпсіз?','Остановиться и сменить путь','Тоқтап, жолды өзгерту','Ускориться','Жылдамдау','Игнорировать сигнал','Белгіні елемеу']]);
unit(2,'Искусственный интеллект','Жасанды интеллект','sparkles-outline',[
['Личные данные и ИИ','Жеке деректер және ЖИ','ИИ-сервису не нужно знать твой адрес, пароль и документы. Обращаться к таким сервисам следует вместе со взрослым.','ЖИ сервисіне мекенжайыңды, құпиясөзіңді, құжаттарыңды білу қажет емес. Мұндай сервистерді ересекпен бірге қолданған дұрыс.','Для сказки о лисе достаточно написать «Придумай сказку о лисе». Настоящий адрес и фамилия не нужны.','Түлкі туралы ертегі үшін «Түлкі туралы ертегі ойлап тап» деу жеткілікті. Нақты мекенжай мен тегің қажет емес.','Что можно включить в запрос о сказке?','Ертегі туралы сұрауға нені қосуға болады?','Вымышленного героя','Ойдан шығарылған кейіпкерді','Домашний адрес','Үй мекенжайын','Пароль','Құпиясөзді'],
['Компьютер тоже ошибается','Компьютер де қателеседі','Уверенный ответ программы не обязательно верный. Проверяй важные факты по учебнику или вместе с учителем.','Программаның сенімді жауабы міндетті түрде дұрыс емес. Маңызды деректерді оқулықпен немесе мұғаліммен бірге тексер.','Программа написала, что у кошки шесть лап. Посмотри на кошку или в книгу: у неё четыре лапы.','Программа мысықта алты аяқ бар деді. Мысыққа не кітапқа қара: оның төрт аяғы бар.','Что делать с сомнительным ответом?','Күмәнді жауаппен не істеу керек?','Проверить по надёжному источнику','Сенімді дереккөзден тексеру','Сразу поверить','Бірден сену','Разослать всем','Бәріне тарату'],
['Как учатся программы','Программалар қалай үйренеді','При обучении ИИ используют примеры. Программа ищет закономерности. Чем разнообразнее подходящие примеры, тем лучше можно проверить её работу.','ЖИ үйретуде мысалдар қолданылады. Программа заңдылықтарды іздейді. Сәйкес мысалдар әртүрлі болса, оның жұмысын жақсырақ тексеруге болады.','Если показать только красные яблоки, программе может быть трудно узнать зелёное. Нужны разные примеры яблок.','Тек қызыл алма көрсетсең, программа жасыл алманы тануда қиналуы мүмкін. Алманың әртүрлі мысалдары керек.','Какие примеры полезнее для узнавания яблок?','Алманы тану үшін қандай мысалдар пайдалы?','Яблоки разных цветов и форм','Түсі мен пішіні әртүрлі алмалар','Одна и та же фотография','Бір ғана фотосурет','Только автомобили','Тек автомобильдер'],
['Рисунок по описанию','Сипаттама бойынша сурет','Чтобы описать рисунок, назови предмет, цвет и детали. Результат ИИ нужно рассмотреть: он может пропустить или перепутать условие.','Суретті сипаттау үшін затты, түсін, бөлшектерін ата. ЖИ нәтижесін қарау керек: ол шартты ұмытуы не шатастыруы мүмкін.','«Синий дом с двумя окнами» точнее, чем «Нарисуй что-нибудь». Проверь цвет дома и число окон.','«Екі терезесі бар көк үй» деген «Бірдеңе сал» дегеннен нақтырақ. Үйдің түсі мен терезелер санын тексер.','Какой запрос понятнее?','Қай сұрау түсініктірек?','Синий дом с двумя окнами','Екі терезесі бар көк үй','Сделай красиво','Әдемі жаса','Что-нибудь','Бірдеңе']]);

unit(3,'Как работает компьютер','Компьютер қалай жұмыс істейді','desktop-outline',[
['Общаемся уважительно','Сыйластықпен сөйлесеміз','В интернете общаются настоящие люди. Не обижай собеседника и не пересылай чужие фото без разрешения. О травле расскажи взрослому.','Интернетте шынайы адамдар сөйлеседі. Әңгімелесушіні ренжітпе, бөтен фотоны рұқсатсыз таратпа. Қудалау болса, ересекке айт.','Если однокласснику пишут обидные слова, не присоединяйся. Поддержи его и попроси помощи у взрослого.','Сыныптасыңа ренжітетін сөз жазса, қосылма. Оны қолдап, ересектен көмек сұра.','Как поступить при травле в чате?','Чатта қудалау болса не істеу керек?','Поддержать и обратиться к взрослому','Қолдап, ересекке айту','Добавить обидное сообщение','Ренжітетін хабарлама қосу','Переслать насмешку всем','Мазақты бәріне жіберу'],
['Внутри компьютера','Компьютердің ішінде','Процессор выполняет команды. Оперативная память хранит данные во время работы. Накопитель сохраняет файлы после выключения.','Процессор командаларды орындайды. Жедел жад жұмыс кезінде деректерді ұстайды. Жинақтауыш өшіргеннен кейін де файлдарды сақтайды.','Несохранённый текст можно потерять при выключении. Команда сохранения записывает файл на накопитель.','Сақталмаған мәтін өшіргенде жоғалуы мүмкін. Сақтау пәрмені файлды жинақтауышқа жазады.','Где остаётся сохранённый файл после выключения?','Өшіргеннен кейін сақталған файл қайда қалады?','На накопителе','Жинақтауышта','Только в оперативной памяти','Тек жедел жадта','В мыши','Тінтуірде'],
['Программы и быстрые команды','Программалар және жылдам пәрмендер','Операционная система управляет устройством. Прикладные программы решают задачи: редактор — для текста, браузер — для сайтов. Сочетания клавиш ускоряют работу.','Операциялық жүйе құрылғыны басқарады. Қолданбалар тапсырмаларды шешеді: редактор — мәтінге, браузер — сайттарға. Перне тіркесімдері жұмысты жылдамдатады.','Во многих программах Windows Ctrl+C копирует выделенное, Ctrl+V вставляет, Ctrl+Z отменяет последнее действие.','Көптеген Windows программасында Ctrl+C ерекшеленгенді көшіреді, Ctrl+V қояды, Ctrl+Z соңғы әрекетті болдырмайды.','Как отменить случайное действие?','Кездейсоқ әрекетті қалай болдырмаймыз?','Ctrl+Z','Ctrl+Z','Ctrl+C','Ctrl+C','Ctrl+V','Ctrl+V']]);
unit(3,'Разработка проекта','Жоба әзірлеу','bulb-outline',[
['Идея и план проекта','Жоба идеясы мен жоспары','Проект начинается с вопроса и цели. Определи, кому нужен результат, какую информацию собрать и какие шаги выполнить.','Жоба сұрақ пен мақсаттан басталады. Нәтиже кімге керек екенін, қандай ақпарат жинап, қандай қадамдар жасау керегін анықта.','Для памятки о воде: изучи способы экономии, выбери три совета, создай иллюстрации и проверь понятность.','Суды үнемдеу жадынамасы үшін: тәсілдерді зертте, үш кеңес таңда, суреттер жаса және түсініктілігін тексер.','С чего начать проект?','Жобаны неден бастаймыз?','С цели и плана','Мақсат пен жоспардан','Со случайных украшений','Кездейсоқ әшекейден','С удаления файлов','Файлдарды жоюдан'],
['Оформляем текст проекта','Жоба мәтінін рәсімдейміз','Разделяй текст на абзацы. Заголовок выделяет главную мысль. Размер, цвет и выравнивание шрифта должны помогать чтению.','Мәтінді абзацтарға бөл. Тақырып негізгі ойды көрсетеді. Қаріп өлшемі, түсі мен туралануы оқуға көмектесуі керек.','После знака препинания ставят пробел. Картинку размещают рядом с нужным абзацем, чтобы она не закрывала слова.','Тыныс белгісінен кейін бос орын қойылады. Суретті тиісті абзац жанына, сөздерді жаппайтындай орналастырады.','Как оформить понятный текст?','Түсінікті мәтінді қалай рәсімдейміз?','Заголовок и короткие абзацы','Тақырып және қысқа абзацтар','Один длинный ряд без пробелов','Бос орынсыз ұзын қатар','Картинка поверх слов','Сөздердің үстіндегі сурет']]);
unit(3,'Создание игры','Ойын жасау','game-controller-outline',[
['Повторяем команды','Командаларды қайталаймыз','Цикл повторяет команды несколько раз. Он сокращает программу. Важно знать, какие команды находятся внутри цикла.','Цикл командаларды бірнеше рет қайталайды. Ол программаны қысқартады. Цикл ішінде қандай командалар бар екенін білу маңызды.','«Повторить 3 раза: шаг, хлопок» даёт три шага и три хлопка. Обе команды повторяются вместе.','«3 рет қайтала: қадам, шапалақ» үш қадам мен үш шапалақ береді. Екі команда бірге қайталанады.','Сколько хлопков получится?','Неше шапалақ болады?','3','3','1','1','6','6'],
['Сцены и фоны','Сахналар мен фондар','Фон задаёт место действия. При смене сцены можно менять фон и положение героев. Фон не является спрайтом.','Фон оқиға орнын көрсетеді. Сахна ауысқанда фон мен кейіпкерлердің орнын өзгертуге болады. Фон спрайт емес.','Сначала герой в школе, потом в парке. Меняем фон школы на парк, а героя оставляем тем же.','Алдымен кейіпкер мектепте, кейін саябақта. Мектеп фонын саябаққа ауыстырамыз, кейіпкер сол күйінде қалады.','Что задаёт место действия?','Оқиғаның орнын не көрсетеді?','Фон','Фон','Пароль','Құпиясөз','Имя папки','Буманың атауы'],
['Управляем персонажем','Кейіпкерді басқарамыз','У каждого спрайта есть своя программа. События связывают действия с нажатием клавиш или сообщениями от других героев.','Әр спрайттың өз программасы бар. Оқиғалар әрекеттерді перне басумен немесе басқа кейіпкерлер хабарымен байланыстырады.','При нажатии стрелки вправо герой движется вправо. Код нужно прикрепить к нужному персонажу.','Оң жақ көрсеткіні басқанда кейіпкер оңға жүреді. Кодты қажетті кейіпкерге бекіту керек.','Где должна быть команда движения героя?','Кейіпкердің қозғалыс командасы қайда болуы керек?','В программе этого спрайта','Осы спрайттың программасында','В имени файла','Файл атауында','В пароле','Құпиясөзде'],
['Анимация костюмов','Костюмдер анимациясы','Костюмы — варианты внешности одного спрайта. Чередуй их с паузой, чтобы движение было заметным.','Костюмдер — бір спрайт келбетінің нұсқалары. Қозғалыс көрінуі үшін оларды кідіріспен кезектестір.','Для шага используй два положения ног. Слишком быстрая смена без паузы выглядит как мелькание.','Қадам үшін аяқтың екі қалпын қолдан. Кідіріссіз өте жылдам ауысу жыпылықтауға ұқсайды.','Что делает анимацию различимой?','Анимацияны анық көрсететін не?','Небольшая пауза между костюмами','Костюмдер арасындағы қысқа кідіріс','Удаление всех костюмов','Барлық костюмді жою','Скрытие героя','Кейіпкерді жасыру'],
['Собираем свою игру','Өз ойынымызды құрастырамыз','Игре нужны цель, правила и управление. После сборки проверь начало, победу и повторный запуск. Ошибка — повод улучшить программу.','Ойынға мақсат, ереже және басқару қажет. Құрастырғаннан кейін басталуын, жеңісті және қайта іске қосылуын тексер. Қате — программаны жақсарту мүмкіндігі.','В игре «Собери яблоки» герой движется стрелками. Победа наступает после трёх яблок. При новом старте счёт обнуляется.','«Алма жина» ойынында кейіпкер көрсеткілермен жүреді. Үш алмадан кейін жеңіс болады. Қайта бастағанда ұпай нөлге түседі.','Что проверить при повторном запуске?','Қайта іске қосқанда нені тексереміз?','Сброс счёта и начальную позицию','Ұпайдың нөлденуін және бастапқы орынды','Только цвет кнопки','Тек батырма түсін','Только название игры','Тек ойын атауын']]);
unit(3,'ИИ в повседневной жизни','Күнделікті өмірдегі ЖИ','sparkles-outline',[
['Где помогает ИИ','ЖИ қайда көмектеседі','ИИ помогает распознавать речь, переводить и искать закономерности. Человек задаёт цель и оценивает результат. Важные решения нельзя слепо доверять программе.','ЖИ сөйлеуді тануға, аударуға, заңдылық табуға көмектеседі. Мақсатты адам қойып, нәтижені бағалайды. Маңызды шешімді программаға соқыр сеніп беруге болмайды.','Переводчик предложил фразу. Прочитай её в контексте: слово может иметь несколько значений.','Аудармашы тіркес ұсынды. Оны мәнмәтінде оқы: сөздің бірнеше мағынасы болуы мүмкін.','Кто проверяет результат ИИ?','ЖИ нәтижесін кім тексереді?','Человек','Адам','Никто','Ешкім','Только принтер','Тек принтер'],
['Ответственное использование ИИ','ЖИ-ді жауапкершілікпен қолдану','Используя помощь ИИ, расскажи об этом учителю. Не выдавай чужую или сгенерированную работу за полностью свою. Не отправляй личные данные.','ЖИ көмегін қолдансаң, мұғалімге айт. Бөтен не жасалған жұмысты толығымен өзімдікі деп көрсетпе. Жеке деректерді жіберме.','Можно сказать: «Идею предложил ИИ, а сюжет и рисунки я доработал сам». Это честно объясняет твой вклад.','«Идеяны ЖИ ұсынды, ал оқиға мен суреттерді өзім толықтырдым» деуге болады. Бұл үлесіңді адал түсіндіреді.','Как честно представить работу с ИИ?','ЖИ көмегімен жасалған жұмысты қалай адал таныстырамыз?','Указать помощь ИИ и свой вклад','ЖИ көмегі мен өз үлесіңді айту','Скрыть помощь','Көмекті жасыру','Приписать всё себе','Бәрін өзімдікі деу'],
['Придумываем сказку','Ертегі ойлап табамыз','Хороший запрос описывает героя, место и задачу. Предложенную историю нужно прочитать, исправить и дополнить собственными идеями.','Жақсы сұрау кейіпкерді, орынды және тапсырманы сипаттайды. Ұсынылған оқиғаны оқып, түзетіп, өз идеяларыңмен толықтыру керек.','«Короткая добрая сказка о зайце, который учится делиться» задаёт героя и смысл. Не добавляй настоящие данные одноклассников.','«Бөлісуді үйренетін қоян туралы қысқа мейірімді ертегі» кейіпкер мен мағынаны береді. Сыныптастарыңның нақты деректерін қоспа.','Что полезно добавить к запросу?','Сұрауға нені қосқан пайдалы?','Героя и задачу истории','Кейіпкер мен оқиға мақсатын','Чужой пароль','Өзгенің құпиясөзін','Домашние адреса','Үй мекенжайларын']]);
unit(3,'Текст, графика и презентация','Мәтін, графика және презентация','albums-outline',[
['Первый слайд','Алғашқы слайд','Презентация состоит из слайдов. Один слайд раскрывает одну мысль. Заголовок помогает понять, о чём идёт речь.','Презентация слайдтардан тұрады. Бір слайд бір ойды ашады. Тақырып не туралы айтылғанын түсінуге көмектеседі.','На слайде о бережном расходе воды достаточно заголовка, двух советов и подходящего рисунка.','Суды үнемдеу слайдына тақырып, екі кеңес және сәйкес сурет жеткілікті.','Сколько главных мыслей лучше поместить на слайд?','Бір слайдқа неше негізгі ой берген дұрыс?','Одну','Біреу','Двадцать','Жиырма','Все мысли проекта сразу','Жобаның барлық ойын бірден'],
['Оформление и переходы','Рәсімдеу және ауысулар','Читаемый шрифт и контраст помогают зрителю. Переход — эффект между слайдами. Одинаковое оформление объединяет презентацию.','Оқылатын қаріп пен контраст көрерменге көмектеседі. Ауысу — слайдтар арасындағы әсер. Бірдей рәсімдеу презентацияны біріктіреді.','Тёмный текст на светлом фоне читать легче, чем светло-жёлтый на белом. Эффекты не должны отвлекать.','Ашық фонда қою мәтін ақ фонда ашық сары мәтіннен жақсы оқылады. Әсерлер назарды бөлмеуі керек.','Какой текст легче прочитать?','Қай мәтінді оқу оңай?','Тёмный на светлом фоне','Ашық фонда қою мәтін','Белый на белом','Ақ фонда ақ мәтін','Очень мелкий','Өте ұсақ мәтін'],
['Фотографии и рисунки','Фотолар мен суреттер','Изображение можно обрезать, повернуть и изменить размер. Сохраняй пропорции, чтобы предметы не растягивались. Указывай источник чужого изображения.','Суретті қиып, бұрып, өлшемін өзгертуге болады. Заттар созылмауы үшін пропорциясын сақта. Бөтен суреттің дереккөзін көрсет.','Если растянуть фото только в ширину, лицо станет слишком широким. Меняй ширину и высоту пропорционально.','Фотоны тек еніне созсаң, бет тым жалпақ болады. Ені мен биіктігін үйлесімді өзгерт.','Как не исказить фотографию?','Фотосуретті қалай бұрмаламаймыз?','Сохранять пропорции','Пропорциясын сақтау','Растянуть только ширину','Тек енін созу','Сжать только высоту','Тек биіктігін қысу'],
['Показываем проект','Жобаны таныстырамыз','Перед выступлением проверь порядок слайдов и читаемость. Рассказывай своими словами, а не читай весь экран. Сохрани готовую работу.','Сөйлемес бұрын слайдтар реті мен оқылуын тексер. Экранды түгел оқымай, өз сөзіңмен айт. Дайын жұмысты сақта.','Начни с цели, покажи результат, объясни вывод. В конце назови источники и ответь на вопросы.','Мақсаттан баста, нәтижені көрсет, қорытындыны түсіндір. Соңында дереккөздерді атап, сұрақтарға жауап бер.','Что полезно сделать до выступления?','Таныстыру алдында не істеген пайдалы?','Проверить и отрепетировать','Тексеріп, жаттығу','Удалить источники','Дереккөздерді жою','Перемешать слайды','Слайдтарды араластыру']]);
unit(3,'Робототехника','Роботтехника','hardware-chip-outline',[
['Рука робота','Роботтың қолы','Мотор может двигать руку робота. Скорость определяет быстроту движения, число оборотов — величину вращения. Проверку начинают осторожно.','Мотор роботтың қолын қозғай алады. Жылдамдық қозғалыстың шапшаңдығын, айналым саны айналу мөлшерін анықтайды. Тексеруді абайлап бастайды.','Один оборот — полный круг, половина оборота — полкруга. Для точного движения важно задать оба параметра.','Бір айналым — толық шеңбер, жарты айналым — жарты шеңбер. Дәл қозғалыс үшін екі параметр де маңызды.','Что задаёт величину вращения?','Айналу мөлшерін не анықтайды?','Число оборотов','Айналым саны','Цвет корпуса','Қорап түсі','Название проекта','Жоба атауы'],
['Циклы для робота','Роботқа арналған циклдер','Повторяющийся маршрут удобно записать циклом. Но робот должен проверять препятствия: повторение не делает путь безопасным само по себе.','Қайталанатын бағытты циклмен жазу ыңғайлы. Бірақ робот кедергілерді тексеруі керек: қайталау жолды өздігінен қауіпсіз етпейді.','Для квадрата повтори четыре раза: ехать прямо, повернуть на четверть круга. Получатся четыре стороны.','Шаршы үшін төрт рет қайтала: түзу жүр, ширек шеңберге бұрыл. Төрт қабырға шығады.','Сколько повторов нужно для четырёх сторон?','Төрт қабырға үшін неше қайталау керек?','4','4','2','2','8','8'],
['Робот-уборщик','Тазалаушы робот','Роботу-уборщику нужен маршрут, который покрывает участок. Он должен объезжать препятствия и завершать работу по условию.','Тазалаушы роботқа аумақты қамтитын бағыт қажет. Ол кедергілерді айналып өтіп, шарт бойынша жұмысын аяқтауы керек.','Проходы рядами помогают убрать участок без больших пропусков. После каждого ряда робот переходит к следующему.','Қатармен жүру аумақты көп жер қалдырмай тазалауға көмектеседі. Әр қатардан кейін робот келесісіне өтеді.','Как лучше покрыть прямоугольный участок?','Тікбұрышты аумақты қалай жақсы қамтимыз?','Последовательно пройти ряды','Қатарларды ретімен өту','Стоять на месте','Орнында тұру','Бесконечно кружить в углу','Бұрышта шексіз айналу']]);

unit(4,'Программирование','Программалау','code-slash-outline',[
['Переменные и счёт','Айнымалылар және ұпай','Переменная хранит значение, которое может меняться. Счёт игры — пример переменной. При новом старте начальное значение задают явно.','Айнымалы өзгеретін мәнді сақтайды. Ойын ұпайы — айнымалының мысалы. Қайта бастағанда бастапқы мәнді нақты қояды.','Сначала счёт равен 0. Каждое яблоко добавляет 1. После трёх яблок значение станет 3.','Алдымен ұпай 0. Әр алма 1 қосады. Үш алмадан кейін мәні 3 болады.','Чему равен счёт после трёх яблок?','Үш алмадан кейін ұпай қанша?','3','3','0','0','1','1'],
['Костюм по событию','Оқиғаға сай костюм','Внешность героя может зависеть от события или состояния. Связывай смену костюма с понятным условием.','Кейіпкер келбеті оқиғаға не күйге байланысты болуы мүмкін. Костюм ауысуын түсінікті шартпен байланыстыр.','Если герой получил щит, покажи костюм со щитом. Когда защита закончилась, верни обычный костюм.','Кейіпкер қалқан алса, қалқаны бар костюмді көрсет. Қорғаныс біткенде қалыпты костюмге қайтар.','Когда возвращаем обычный костюм?','Қалыпты костюмге қашан қайтамыз?','Когда закончилась защита','Қорғаныс біткенде','При любом звуке','Кез келген дыбыста','Никогда','Ешқашан'],
['Логика: И, ИЛИ, НЕ','Логика: ЖӘНЕ, НЕМЕСЕ, ЕМЕС','И требует выполнения обоих условий. ИЛИ достаточно хотя бы одного. НЕ меняет истинность условия на противоположную.','ЖӘНЕ екі шарттың да орындалуын талап етеді. НЕМЕСЕ үшін кемінде біреуі жеткілікті. ЕМЕС шарттың ақиқаттық мәнін кері өзгертеді.','Дверь открывается, если есть ключ И нажата кнопка. Только ключ без нажатия не откроет дверь.','Кілт бар ЖӘНЕ батырма басылса, есік ашылады. Батырманы баспай, тек кілтпен есік ашылмайды.','Для условия И сколько частей должны быть верны?','ЖӘНЕ шартында неше бөлік ақиқат болуы керек?','Обе','Екеуі де','Только одна','Тек біреуі','Ни одна','Ешқайсысы'],
['Сравниваем значения','Мәндерді салыстырамыз','Операторы сравнения проверяют значения: больше, меньше или равно. Результат проверки — истина или ложь.','Салыстыру операторлары мәндерді тексереді: үлкен, кіші немесе тең. Тексеру нәтижесі — ақиқат не жалған.','Если счёт больше 5, выдаём бонус. При счёте 5 условие ложно: пять не больше пяти.','Ұпай 5-тен үлкен болса, бонус береміз. Ұпай 5 болғанда шарт жалған: бес бестен үлкен емес.','Счёт 5. Условие «счёт > 5» верно?','Ұпай 5. «Ұпай > 5» шарты дұрыс па?','Нет','Жоқ','Да','Иә','Зависит от цвета','Түске байланысты'],
['Проектируем игру','Ойын жобалаймыз','Составь сценарий, правила, условия победы и проигрыша. Используй переменные и проверки. Тестируй крайние случаи.','Сценарий, ережелер, жеңіс пен жеңіліс шарттарын құрастыр. Айнымалылар мен тексерулерді қолдан. Шеткі жағдайларды сына.','Проверь, что будет при нулевом счёте, последнем предмете и повторном старте. Игра должна вести себя предсказуемо.','Нөл ұпайда, соңғы затта және қайта бастағанда не болатынын тексер. Ойын түсінікті түрде әрекет етуі керек.','Какой тест особенно полезен?','Қай сынақ әсіресе пайдалы?','Победа и повторный старт','Жеңіс пен қайта бастау','Только запуск меню','Тек мәзірді ашу','Только выбор названия','Тек атау таңдау']]);
unit(4,'Робототехника','Роботтехника','hardware-chip-outline',[
['Датчик цвета','Түс датчигі','Датчик цвета различает цвет поверхности или измеряет отражённый свет. Освещение влияет на показания, поэтому датчик нужно проверять.','Түс датчигі бет түсін ажыратады немесе шағылған жарықты өлшейді. Жарықтандыру көрсеткішке әсер етеді, сондықтан датчикті тексеру керек.','На чёрной линии отражается меньше света, чем на белом поле. Программа использует это различие для движения.','Қара сызық ақ алаңға қарағанда жарықты аз шағылдырады. Программа қозғалу үшін осы айырманы қолданады.','Что может различать датчик цвета?','Түс датчигі нені ажырата алады?','Цвет поверхности','Бет түсін','Пароль пользователя','Пайдаланушы құпиясөзін','Смысл рассказа','Әңгіме мағынасын'],
['Робот и светофор','Робот және бағдаршам','Сигнал датчика можно связать с действием. Для разных цветов задают разные правила. Неизвестный сигнал тоже нужно обработать.','Датчик белгісін әрекетпен байланыстыруға болады. Әр түске бөлек ереже беріледі. Белгісіз белгіні де өңдеу керек.','Красный — остановка, зелёный — движение. Если цвет не распознан, безопаснее остановиться и проверить.','Қызыл — тоқтау, жасыл — жүру. Түс танылмаса, тоқтап, тексеру қауіпсізірек.','Что делать при нераспознанном сигнале?','Белгі танылмаса не істеу керек?','Остановиться и проверить','Тоқтап, тексеру','Ускориться','Жылдамдау','Всегда ехать вперёд','Әрқашан алға жүру'],
['Измеряем расстояние','Қашықтықты өлшейміз','Ультразвуковой датчик оценивает расстояние по отражённому сигналу. Он помогает заметить препятствие до столкновения.','Ультрадыбыстық датчик шағылған белгі арқылы қашықтықты бағалайды. Ол соқтығысудан бұрын кедергіні байқауға көмектеседі.','Если расстояние меньше 10 см, робот останавливается. Датчик измеряет расстояние, а решение задаёт программа.','Қашықтық 10 см-ден аз болса, робот тоқтайды. Датчик қашықтықты өлшейді, шешімді программа береді.','Кто задаёт действие при близкой стене?','Жақын қабырға кезіндегі әрекетті не анықтайды?','Программа','Программа','Цвет колёс','Дөңгелек түсі','Название датчика','Датчик атауы'],
['Лабиринт с датчиком','Датчикпен лабиринттен өту','Маршрут с датчиком реагирует на препятствия. Проверку расстояния нужно повторять во время движения, а не только в начале.','Датчикті бағыт кедергілерге жауап береді. Қашықтықты тек басында емес, қозғалыс кезінде де қайта тексеру керек.','Повторяй: измерить расстояние; если близко — остановиться и повернуть; иначе — двигаться.','Қайтала: қашықтықты өлше; жақын болса — тоқтап бұрыл; әйтпесе — жүр.','Когда проверять расстояние?','Қашықтықты қашан тексереміз?','Регулярно во время движения','Қозғалыс кезінде үнемі','Только после столкновения','Тек соқтығысқаннан кейін','Один раз при сборке','Құрастыру кезінде бір рет'] ,
['Кегельринг','Кегль-ринг','В кегельринге робот выталкивает предметы за границу круга и сам остаётся внутри. Нужны обнаружение предметов и контроль границы.','Кегль-рингте робот заттарды шеңберден шығарып, өзі ішінде қалады. Заттарды анықтау және шекараны бақылау қажет.','Ультразвук помогает найти предмет, датчик цвета — заметить линию круга. При линии робот должен изменить движение.','Ультрадыбыс затты табуға, түс датчигі шеңбер сызығын байқауға көмектеседі. Сызықта робот қозғалысын өзгертуі керек.','Какой датчик помогает заметить линию?','Сызықты байқауға қай датчик көмектеседі?','Датчик цвета','Түс датчигі','Микрофон без программы','Программасыз микрофон','Только мотор','Тек мотор']]);
unit(4,'Мультимедийные презентации','Мультимедиалық презентациялар','albums-outline',[
['Ищем и проверяем информацию','Ақпаратты іздеп, тексереміз','Подбирай точные ключевые слова. Сравнивай источники, проверяй автора и дату. Закладки сохраняют адрес страницы, история — список посещений.','Нақты түйінді сөздерді таңда. Дереккөздерді салыстыр, авторы мен күнін тексер. Бетбелгі бет мекенжайын, тарих кірген беттер тізімін сақтайды.','Для доклада о Балхаше ищи сведения в учебнике и надёжном справочнике. Первый результат поиска не обязательно лучший.','Балқаш туралы баяндамаға мәліметті оқулық пен сенімді анықтамадан ізде. Іздеудің бірінші нәтижесі міндетті түрде ең жақсысы емес.','Как проверить спорный факт?','Даулы деректі қалай тексереміз?','Сравнить надёжные источники','Сенімді дереккөздерді салыстыру','Верить первому заголовку','Бірінші тақырыпқа сену','Считать рекламу доказательством','Жарнаманы дәлел санау'],
['Звук в презентации','Презентациядағы дыбыс','Звук должен помогать объяснению. Настрой момент запуска и громкость. Проверь, что речь слышна, а музыка не перекрывает её.','Дыбыс түсіндіруге көмектесуі керек. Басталу уақытын және қаттылығын бапта. Сөз естіліп, музыка оны баспайтынын тексер.','Если рассказ звучит одновременно с громкой музыкой, уменьши музыку или убери её во время речи.','Әңгіме қатты музыкамен қатар шықса, музыканы бәсеңдет не сөз кезінде өшір.','Как сделать речь разборчивее?','Сөзді қалай анық естіртеміз?','Уменьшить фоновую музыку','Фондық музыканы бәсеңдету','Усилить все звуки','Барлық дыбысты күшейту','Запустить ещё одну запись','Тағы бір жазба қосу'],
['Видео в презентации','Презентациядағы бейне','Выбирай короткий фрагмент, связанный с темой. Проверь воспроизведение заранее. Для офлайн-показа нужен доступный на устройстве файл.','Тақырыпқа сай қысқа үзінді таңда. Ойнатылуын алдын ала тексер. Офлайн көрсету үшін құрылғыдағы қолжетімді файл керек.','Ссылка на ролик может не работать без сети. Встроенный разрешённый видеофайл нужно проверить в режиме без интернета.','Бейне сілтемесі желісіз жұмыс істемеуі мүмкін. Рұқсат етілген кірістірілген бейнефайлды интернетсіз тексеру керек.','Что проверить перед офлайн-показом?','Офлайн көрсету алдында нені тексереміз?','Работает ли видео без сети','Бейне желісіз жұмыс істей ме','Только имя слайда','Тек слайд атауын','Число подписчиков автора','Автордың жазылушы санын'],
['Анимация и переходы','Анимация және ауысулар','Анимация меняет объект на слайде, переход меняет слайды. Используй эффекты, чтобы показывать шаги объяснения по очереди.','Анимация слайдтағы нысанды, ауысу слайдтарды өзгертеді. Әсерлерді түсіндіру қадамдарын кезекпен көрсету үшін қолдан.','Три этапа роста растения появляются по одному. Зритель видит порядок и не отвлекается на лишние движения.','Өсімдік өсуінің үш кезеңі бір-бірден шығады. Көрермен ретін көріп, артық қозғалысқа алаңдамайды.','Что относится к анимации объекта?','Нысан анимациясына не жатады?','Появление рисунка на слайде','Слайдта суреттің пайда болуы','Смена одного слайда другим','Бір слайдтың екіншісіне ауысуы','Имя презентации','Презентация атауы']]);
unit(4,'Компьютеры будущего','Болашақ компьютерлері','planet-outline',[
['Передаём данные','Деректерді жібереміз','Файлы имеют размер. Большое видео обычно передаётся дольше короткого текста при той же скорости сети. Перед отправкой проверь получателя и содержимое.','Файлдардың көлемі болады. Желі жылдамдығы бірдей болса, үлкен бейне қысқа мәтіннен ұзақ жіберіледі. Жібермес бұрын алушы мен мазмұнды тексер.','Файл 20 МБ больше файла 2 МБ в десять раз. Для обмена можно выбрать меньшую копию, сохранив нужное качество.','20 МБ файл 2 МБ файлдан он есе үлкен. Алмасу үшін қажетті сапаны сақтап, кішірек көшірме таңдауға болады.','Какой файл больше?','Қай файл үлкен?','20 МБ','20 МБ','2 МБ','2 МБ','Размеры одинаковые','Көлемдері бірдей'],
['Надёжный пароль','Сенімді құпиясөз','Используй длинный уникальный пароль. Не включай имя и дату рождения. Никому не отправляй пароль и одноразовый код.','Ұзын әрі бірегей құпиясөз қолдан. Атың мен туған күніңді қоспа. Құпиясөз бен бір реттік кодты ешкімге жіберме.','Длинная фраза из несвязанных слов лучше «123456». Для разных сервисов нужны разные пароли. Пример из урока не используй как настоящий пароль.','Байланыссыз сөздерден ұзын тіркес «123456»-дан жақсы. Әр сервиске бөлек құпиясөз керек. Сабақ мысалын нақты құпиясөз етпе.','Какой подход надёжнее?','Қай тәсіл сенімдірек?','Длинный уникальный пароль','Ұзын бірегей құпиясөз','Один короткий пароль везде','Барлық жерде бір қысқа құпиясөз','Имя и день рождения','Атың мен туған күнің'],
['Технологии будущего: проект','Болашақ технологиялары: жоба','Придумай устройство, решающее реальную задачу. Опиши входные данные, действия и результат. Подумай о пользе и ограничениях.','Нақты мәселені шешетін құрылғы ойлап тап. Кіріс деректерін, әрекеттерін, нәтижесін сипатта. Пайдасы мен шектеулерін ойла.','Умная теплица измеряет влажность и поливает растения по условию. Нужно предусмотреть поломку датчика и ручное управление.','Ақылды жылыжай ылғалды өлшеп, шартпен өсімдікті суарады. Датчик бұзылуын және қолмен басқаруды ескеру керек.','Что делает проект убедительнее?','Жобаны не сенімдірек етеді?','Задача, принцип работы и ограничения','Мәселе, жұмыс қағидасы және шектеулер','Только красивое название','Тек әдемі атау','Обещание решать всё','Бәрін шешуге уәде беру']]);
unit(4,'Понимаем искусственный интеллект','Жасанды интеллектті түсінеміз','sparkles-outline',[
['Генеративные модели','Генеративті модельдер','Генеративный ИИ создаёт текст, изображения и другой контент по запросу. Он использует закономерности обучения, а не гарантирует истинность каждого ответа.','Генеративті ЖИ сұрау бойынша мәтін, сурет және басқа мазмұн жасайды. Ол үйренген заңдылықтарды қолданады, әр жауаптың ақиқаттығына кепілдік бермейді.','Красивый рассказ о выдуманной планете подходит для фантастики, но не становится научным фактом.','Ойдан шығарылған ғаламшар туралы әдемі әңгіме қиялға жарайды, бірақ ғылыми дерек болмайды.','Любой ли текст ИИ является фактом?','ЖИ-дің кез келген мәтіні дерек пе?','Нет, его нужно проверять','Жоқ, оны тексеру керек','Да, если он длинный','Иә, егер ұзын болса','Да, если написан уверенно','Иә, сенімді жазылса'],
['Составляем понятный запрос','Түсінікті сұрау құрамыз','Промпт — инструкция для модели. Укажи задачу, нужные условия и формат ответа. Не добавляй персональные данные.','Промпт — модельге арналған нұсқау. Тапсырманы, қажетті шарттарды, жауап пішімін көрсет. Жеке деректерді қоспа.','«Объясни круговорот воды ученику 4 класса в трёх коротких пунктах» задаёт тему, аудиторию и формат.','«Су айналымын 4-сынып оқушысына үш қысқа тармақпен түсіндір» тақырыпты, аудиторияны, пішімді көрсетеді.','Что уточняет хороший промпт?','Жақсы промпт нені нақтылайды?','Задачу, условия и формат','Тапсырманы, шартты, пішімді','Только слово «срочно»','Тек «шұғыл» сөзін','Пароль ученика','Оқушының құпиясөзін'],
['Помощник, а не автор за тебя','Көмекші, сенің орныңа автор емес','ИИ может предложить идеи или объяснение. Но тренироваться решать задачи нужно самому. Следуй правилам учителя и обозначай помощь ИИ.','ЖИ идея не түсіндіру ұсына алады. Бірақ есеп шешуді өзің үйренуің керек. Мұғалім ережесін сақтап, ЖИ көмегін көрсет.','Попросить подсказку к задаче полезнее, чем переписать готовый ответ и не понять решение.','Есепке кеңес сұрау дайын жауапты түсінбей көшіргеннен пайдалырақ.','Как использовать ИИ для обучения?','ЖИ-ді оқу үшін қалай қолданамыз?','Попросить объяснение и решить самому','Түсіндіру сұрап, өзің шешу','Сдать чужой ответ как свой','Бөтен жауапты өзімдікі деп тапсыру','Не читать полученный ответ','Алған жауапты оқымау'],
['Проверяем ответ ИИ','ЖИ жауабын тексереміз','Выдели проверяемые утверждения. Найди независимый надёжный источник. Проверь даты, числа и ссылки: модель может придумать даже источник.','Тексерілетін тұжырымдарды бөліп ал. Тәуелсіз сенімді дереккөз тап. Күндерді, сандарды, сілтемелерді тексер: модель дереккөзді де ойдан шығаруы мүмкін.','Если ИИ назвал автора книги, открой каталог библиотеки или саму книгу. Повторный вопрос той же модели не заменяет проверку.','ЖИ кітап авторын атаса, кітапхана каталогын не кітаптың өзін аш. Сол модельден қайта сұрау тексеруді алмастырмайды.','Что надёжнее повторного вопроса тому же ИИ?','Сол ЖИ-ден қайта сұрағаннан не сенімдірек?','Проверка по независимому источнику','Тәуелсіз дереккөзден тексеру','Просьба отвечать увереннее','Сенімдірек жауап беруді сұрау','Копирование ответа','Жауапты көшіру'],
['Профессии и новые инструменты','Мамандықтар және жаңа құралдар','ИИ меняет отдельные задачи в профессиях. Людям нужны знания, творчество, общение и ответственность. Инструмент не снимает ответственности с человека.','ЖИ мамандықтардағы жеке міндеттерді өзгертеді. Адамға білім, шығармашылық, қарым-қатынас және жауапкершілік қажет. Құрал адамды жауапкершіліктен босатпайды.','Дизайнер может получить варианты рисунка от ИИ, но сам выбирает подходящий, проверяет детали и учитывает задачу заказчика.','Дизайнер ЖИ-ден сурет нұсқаларын ала алады, бірақ сәйкесін өзі таңдап, бөлшектерді тексереді және тапсырыс мақсатын ескереді.','Что остаётся задачей человека?','Адамның міндеті болып не қалады?','Оценивать результат и отвечать за решение','Нәтижені бағалап, шешімге жауап беру','Всегда верить программе','Программаға әрқашан сену','Не изучать профессию','Мамандықты үйренбеу']]);

function set(id: string, activity: Activity) { all.find(l=>l.id===id)!.activity=activity; }
function order(id: string, items: [string,string][]) { const l=all.find(l=>l.id===id)!; set(id,{kind:'order',prompt:b('Собери действия в правильном порядке','Әрекеттерді дұрыс ретпен құрастыр'),items:items.map(x=>b(...x)),why:l.cards[1].text}); }
